/// A fixed-capacity least-recently-used cache.
///
/// Entries live in contiguous storage and are threaded onto an intrusive
/// doubly linked list (ordered from most to least recently used) by index,
/// so every operation runs in O(1) expected time without per-node allocation.
struct LRUCache<Key: Hashable, Value> {
    private struct Node {
        var key: Key
        var value: Value
        var prev: Int
        var next: Int
    }

    private static var none: Int { -1 }

    let capacity: Int
    private var index: [Key: Int] = [:]
    private var nodes: [Node] = []
    private var freeSlots: [Int] = []
    private var head = LRUCache.none  // most recently used
    private var tail = LRUCache.none  // least recently used

    init(capacity: Int) {
        precondition(capacity > 0, "capacity must be positive")
        self.capacity = capacity
        let initial = min(capacity, 1 << 16)
        index.reserveCapacity(initial)
        nodes.reserveCapacity(initial)
    }

    var count: Int { index.count }

    /// Returns the value for `key`, marking it as most recently used.
    mutating func value(forKey key: Key) -> Value? {
        guard let slot = index[key] else { return nil }
        moveToFront(slot)
        return nodes[slot].value
    }

    /// Inserts or overwrites `key`, marking it as most recently used and
    /// evicting the least recently used entry if capacity is exceeded.
    mutating func setValue(_ value: Value, forKey key: Key) {
        if let slot = index[key] {
            nodes[slot].value = value
            moveToFront(slot)
            return
        }
        if index.count >= capacity {
            evictLeastRecentlyUsed()
        }
        let node = Node(key: key, value: value, prev: Self.none, next: Self.none)
        let slot: Int
        if let reused = freeSlots.popLast() {
            nodes[reused] = node
            slot = reused
        } else {
            slot = nodes.count
            nodes.append(node)
        }
        index[key] = slot
        pushFront(slot)
    }

    /// Removes `key`, returning whether it was present.
    @discardableResult
    mutating func removeValue(forKey key: Key) -> Bool {
        guard let slot = index.removeValue(forKey: key) else { return false }
        unlink(slot)
        freeSlots.append(slot)
        return true
    }

    // MARK: - List maintenance

    private mutating func evictLeastRecentlyUsed() {
        let slot = tail
        guard slot != Self.none else { return }
        index.removeValue(forKey: nodes[slot].key)
        unlink(slot)
        freeSlots.append(slot)
    }

    private mutating func moveToFront(_ slot: Int) {
        guard slot != head else { return }
        unlink(slot)
        pushFront(slot)
    }

    private mutating func pushFront(_ slot: Int) {
        nodes[slot].prev = Self.none
        nodes[slot].next = head
        if head != Self.none {
            nodes[head].prev = slot
        } else {
            tail = slot
        }
        head = slot
    }

    private mutating func unlink(_ slot: Int) {
        let prev = nodes[slot].prev
        let next = nodes[slot].next
        if prev != Self.none {
            nodes[prev].next = next
        } else {
            head = next
        }
        if next != Self.none {
            nodes[next].prev = prev
        } else {
            tail = prev
        }
        nodes[slot].prev = Self.none
        nodes[slot].next = Self.none
    }
}

/// Reads a capacity followed by cache commands from standard input and
/// writes each command's result to standard output.

/// Buffers output and flushes it in large chunks to keep I/O cheap.
struct OutputBuffer {
    private var buffer = ""
    private let flushThreshold = 1 << 16

    mutating func writeLine<S: StringProtocol>(_ line: S) {
        buffer += line
        buffer += "\n"
        if buffer.utf8.count >= flushThreshold {
            flush()
        }
    }

    mutating func flush() {
        guard !buffer.isEmpty else { return }
        print(buffer, terminator: "")
        buffer.removeAll(keepingCapacity: true)
    }
}

extension String {
    /// Splits the string on ASCII spaces, dropping empty tokens and a trailing
    /// carriage return. Works on UTF-8 code units, avoiding the cost of
    /// grapheme-cluster segmentation.
    func asciiTokens() -> [Substring] {
        let space = UInt8(ascii: " ")
        let utf8 = self.utf8
        var end = utf8.endIndex
        if let last = utf8.indices.last, utf8[last] == UInt8(ascii: "\r") {
            end = last
        }
        var tokens: [Substring] = []
        tokens.reserveCapacity(3)
        var cursor = utf8.startIndex
        while cursor < end {
            if utf8[cursor] == space {
                cursor = utf8.index(after: cursor)
                continue
            }
            let tokenEnd = utf8[cursor..<end].firstIndex(of: space) ?? end
            tokens.append(self[cursor..<tokenEnd])
            cursor = tokenEnd
        }
        return tokens
    }
}

func run() {
    guard let firstLine = readLine(),
          let first = firstLine.asciiTokens().first,
          let capacity = Int(first),
          capacity > 0
    else { return }

    var cache = LRUCache<String, String>(capacity: capacity)
    var output = OutputBuffer()

    while let line = readLine() {
        let tokens = line.asciiTokens()
        guard let command = tokens.first else { continue }

        switch (command, tokens.count) {
        case ("SET", 3):
            cache.setValue(String(tokens[2]), forKey: String(tokens[1]))
        case ("GET", 2):
            output.writeLine(cache.value(forKey: String(tokens[1])) ?? "NULL")
        case ("DEL", 2):
            output.writeLine(cache.removeValue(forKey: String(tokens[1])) ? "1" : "0")
        case ("SIZE", 1):
            output.writeLine(String(cache.count))
        default:
            continue  // Ignore malformed commands.
        }
    }
    output.flush()
}

run()
